const config = {
  "previewFeatures": [],
  "clientVersion": "7.8.0",
  "engineVersion": "3c6e192761c0362d496ed980de936e2f3cebcd3a",
  "activeProvider": "mysql",
  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"mysql\"\n}\n\n/////////////////////////////\n// 🔓 PUBLIC / SYSTEM LEVEL\n/////////////////////////////\n\nmodel School {\n  id            Int                  @id @default(autoincrement())\n  name          String\n  email         String               @unique\n  phone         String?\n  status        SchoolStatus         @default(PENDING)\n  sections      Section[]\n  subscriptions SchoolSubscription[]\n  users         User[]\n  teachers      Teacher[]\n  timetables    Timetable[]\n  timings       SchoolTiming[]\n  periods       Period[]\n  days          Day[]\n  parents       Parent[]\n  academicYears AcademicYear[]\n  students      Student[]\n  admissions    Admission[]\n  exams         Exam[]\n  classes       Class[]\n  feeHeads      FeeHead[]\n\n  transportRoutes TransportRoute[]\n\n  bookPackages BookPackage[]\n\n  feeStructures FeeStructure[]\n\n  studentFees StudentFee[]\n\n  paymentReceipts PaymentReceipt[]\n  academicRecords StudentAcademicRecord[]\n\n  studentAttendanceSessions StudentAttendanceSession[] @relation(\"SchoolStudentAttendanceSessions\")\n\n  employeeAttendances EmployeeAttendance[] @relation(\"SchoolEmployeeAttendances\")\n  createdAt           DateTime             @default(now())\n  updatedAt           DateTime             @updatedAt\n}\n\nenum SchoolStatus {\n  PENDING\n  ACTIVE\n  BLOCKED\n}\n\nmodel Plan {\n  id       Int    @id @default(autoincrement())\n  name     String @unique\n  price    Float\n  duration Int // days\n  features Json // [\"ATTENDANCE\",\"FEES\",\"EXAMS\"]\n\n  subscriptions SchoolSubscription[]\n  createdAt     DateTime             @default(now())\n  updatedAt     DateTime             @updatedAt\n}\n\nmodel SchoolSubscription {\n  id        Int                @id @default(autoincrement())\n  schoolId  Int\n  planId    Int\n  startDate DateTime\n  endDate   DateTime\n  status    SubscriptionStatus\n\n  school    School   @relation(fields: [schoolId], references: [id])\n  plan      Plan     @relation(fields: [planId], references: [id])\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n\nenum SubscriptionStatus {\n  ACTIVE\n  EXPIRED\n  CANCELLED\n}\n\nmodel SchoolRequest {\n  id         Int           @id @default(autoincrement())\n  schoolName String\n  email      String\n  phone      String\n  status     RequestStatus @default(PENDING)\n  createdAt  DateTime      @default(now())\n  updatedAt  DateTime      @updatedAt\n}\n\nenum RequestStatus {\n  PENDING\n  APPROVED\n  REJECTED\n}\n\nmodel Transaction {\n  id        Int           @id @default(autoincrement())\n  schoolId  Int\n  amount    Float\n  gateway   String\n  reference String\n  status    PaymentStatus\n  createdAt DateTime      @default(now())\n}\n\nenum PaymentStatus {\n  SUCCESS\n  FAILED\n  PENDING\n}\n\n/////////////////////////////\n// 🔐 AUTH & RBAC\n/////////////////////////////\n\nmodel User {\n  id            Int     @id @default(autoincrement())\n  name          String\n  email         String  @unique\n  password      String\n  isActive      Boolean @default(true)\n  isDeleted     Boolean @default(false)\n  emailVerified Boolean @default(false)\n\n  schoolId                  Int?\n  school                    School?                    @relation(fields: [schoolId], references: [id])\n  markedAttendances         StudentAttendanceSession[]\n  employeeAttendanceRecords EmployeeAttendance[]\n  roles                     UserRole[]\n  tokens                    Token[]\n  teacher                   Teacher?\n  student                   Student?\n  parent                    Parent?\n  userPermissions           UserPermission[]\n  paymentReceipts           PaymentReceipt[]\n  createdAt                 DateTime                   @default(now())\n  updatedAt                 DateTime                   @updatedAt\n}\n\nmodel Teacher {\n  id              Int              @id @default(autoincrement())\n  userId          Int\n  schoolId        Int\n  teacherCode     String           @unique\n  phone           String?\n  gender          String?\n  joiningDate     DateTime?\n  qualification   String?\n  user            User             @relation(fields: [userId], references: [id])\n  school          School           @relation(fields: [schoolId], references: [id])\n  classTeachers   ClassTeacher[]\n  teacherSubjects TeacherSubject[]\n\n  timetables Timetable[]\n  createdAt  DateTime    @default(now())\n  updatedAt  DateTime    @updatedAt\n\n  @@unique([userId])\n}\n\nmodel Role {\n  id          Int              @id @default(autoincrement())\n  name        String\n  schoolId    Int?\n  profileType String?\n  users       UserRole[]\n  permissions RolePermission[]\n  createdAt   DateTime         @default(now())\n  updatedAt   DateTime         @updatedAt\n\n  @@unique([name, schoolId])\n}\n\nmodel Permission {\n  id              Int              @id @default(autoincrement())\n  key             String           @unique\n  description     String?\n  roles           RolePermission[]\n  userPermissions UserPermission[]\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n}\n\nmodel UserRole {\n  userId Int\n  roleId Int\n\n  user User @relation(fields: [userId], references: [id])\n  role Role @relation(fields: [roleId], references: [id])\n\n  @@id([userId, roleId])\n}\n\nmodel UserPermission {\n  id           Int     @id @default(autoincrement())\n  userId       Int\n  permissionId Int\n  granted      Boolean @default(true)\n\n  user       User       @relation(fields: [userId], references: [id])\n  permission Permission @relation(fields: [permissionId], references: [id])\n\n  @@unique([userId, permissionId])\n}\n\nmodel RolePermission {\n  roleId       Int\n  permissionId Int\n\n  role       Role       @relation(fields: [roleId], references: [id])\n  permission Permission @relation(fields: [permissionId], references: [id])\n\n  @@id([roleId, permissionId])\n}\n\nmodel Token {\n  id        Int       @id @default(autoincrement())\n  userId    Int\n  tokenHash String    @unique\n  type      TokenType\n  expiresAt DateTime\n  isUsed    Boolean   @default(false)\n  isRevoked Boolean   @default(false)\n  userAgent String?\n  ipAddress String?\n  createdAt DateTime  @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@index([userId, type])\n}\n\nenum TokenType {\n  ACCESS\n  REFRESH\n  RESET_PASSWORD\n  VERIFY_EMAIL\n  SET_PASSWORD\n}\n\n/////////////////////////////\n// 🎓 ACADEMIC\n/////////////////////////////\nmodel Class {\n  id Int @id @default(autoincrement())\n\n  // =========================================\n  // BASIC INFO\n  // =========================================\n\n  name String\n\n  description String?\n\n  schoolId Int\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  // =========================================\n  // CLASS SETTINGS\n  // =========================================\n\n  maxStudents Int?\n\n  isActive Boolean @default(true)\n\n  isDeleted Boolean @default(false)\n\n  // =========================================\n  // RELATIONS\n  // =========================================\n\n  sections Section[]\n\n  syllabi Syllabus[]\n\n  exams Exam[]\n\n  classTeachers ClassTeacher[]\n\n  teacherSubjects TeacherSubject[]\n\n  timetables Timetable[]\n\n  admissions Admission[]\n\n  feeStructures FeeStructure[]\n\n  academicRecords StudentAcademicRecord[]\n\n  studentAttendanceSessions StudentAttendanceSession[]\n  bookPackages              BookPackage[]\n\n  // =========================================\n  // AUDIT\n  // =========================================\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =========================================\n  // INDEXES\n  // =========================================\n\n  @@unique([name, schoolId])\n  @@index([schoolId])\n  @@index([isActive])\n  @@index([isDeleted])\n}\n\nmodel Section {\n  id Int @id @default(autoincrement())\n\n  name String\n\n  classId Int\n\n  schoolId Int\n\n  capacity Int?\n\n  description String?\n\n  isActive Boolean @default(true)\n\n  class Class @relation(fields: [classId], references: [id])\n\n  school                    School                     @relation(fields: [schoolId], references: [id])\n  studentAttendanceSessions StudentAttendanceSession[]\n  classTeachers             ClassTeacher[]\n\n  teacherSubjects TeacherSubject[]\n\n  timetables Timetable[]\n\n  admissions      Admission[]\n  exams           Exam[]\n  academicRecords StudentAcademicRecord[]\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  @@unique([schoolId, name, classId])\n}\n\nmodel Grade {\n  id          Int        @id @default(autoincrement())\n  name        String\n  schoolId    Int\n  description String?\n  isActive    Boolean    @default(true)\n  isDeleted   Boolean    @default(false)\n  syllabi     Syllabus[]\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  @@unique([name, schoolId])\n}\n\nmodel Subject {\n  id              Int              @id @default(autoincrement())\n  name            String\n  description     String?\n  isActive        Boolean          @default(true)\n  schoolId        Int\n  code            String\n  maxMarks        Int? // ✅ ADD\n  passMarks       Int?\n  syllabi         Syllabus[]\n  teacherSubjects TeacherSubject[]\n  examSubjects    ExamSubject[]\n  timetables      Timetable[]\n  createdAt       DateTime         @default(now())\n  updatedAt       DateTime         @updatedAt\n\n  @@unique([code, schoolId])\n}\n\nmodel Syllabus {\n  id          Int         @id @default(autoincrement())\n  subjectId   Int\n  gradeId     Int?\n  classId     Int?\n  schoolId    Int\n  description String?\n  type        SubjectType @default(CORE)\n  chapters    Json\n  maxMarks    Int?\n  passMarks   Int?\n  isActive    Boolean     @default(true)\n  isDeleted   Boolean     @default(false)\n  subject     Subject     @relation(fields: [subjectId], references: [id])\n  grade       Grade?      @relation(fields: [gradeId], references: [id])\n  class       Class?      @relation(fields: [classId], references: [id])\n  createdAt   DateTime    @default(now())\n  updatedAt   DateTime    @updatedAt\n\n  @@unique([subjectId, gradeId, classId, schoolId])\n}\n\nenum SubjectType {\n  CORE\n  EXTRA\n  THEORY\n  PRACTICAL\n  BOTH\n}\n\nmodel ClassTeacher {\n  id Int @id @default(autoincrement())\n\n  teacherId Int\n  classId   Int\n  sectionId Int\n\n  teacher Teacher @relation(fields: [teacherId], references: [id])\n  class   Class   @relation(fields: [classId], references: [id])\n  section Section @relation(fields: [sectionId], references: [id])\n\n  createdAt DateTime @default(now())\n\n  // ⭐ ek class + section ka sirf 1 class teacher\n  @@unique([classId, sectionId])\n}\n\nmodel Day {\n  id         Int         @id @default(autoincrement())\n  schoolId   Int\n  name       String\n  shortName  String\n  order      Int\n  maxPeriods Int\n  isActive   Boolean     @default(true)\n  isHalfDay  Boolean     @default(false)\n  timetables Timetable[]\n\n  school  School   @relation(fields: [schoolId], references: [id])\n  periods Period[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([schoolId, name])\n}\n\nmodel TeacherSubject {\n  id Int @id @default(autoincrement())\n\n  teacherId Int\n  subjectId Int\n  classId   Int\n  sectionId Int\n  // schoolId Int\n\n  teacher Teacher @relation(fields: [teacherId], references: [id])\n  subject Subject @relation(fields: [subjectId], references: [id])\n  class   Class   @relation(fields: [classId], references: [id])\n  section Section @relation(fields: [sectionId], references: [id])\n\n  // ⭐ same subject same class same section duplicate nahi\n  // @@unique([teacherId, subjectId, classId, sectionId])\n  // @@unique([schoolId, teacherId, subjectId, classId, sectionId])\n}\n\nmodel SchoolTiming {\n  id           Int    @id @default(autoincrement())\n  schoolId     Int\n  academicYear String\n\n  type TimingType @default(REGULAR)\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([schoolId, academicYear, type])\n}\n\nenum TimingType {\n  REGULAR\n  WINTER\n  RAMADAN\n  EXAM\n}\n\nmodel Period {\n  id             Int        @id @default(autoincrement())\n  schoolId       Int\n  academicYearId Int\n  timingType     TimingType @default(REGULAR)\n\n  dayId        Int\n  periodNumber Int\n\n  startTime String\n  endTime   String\n\n  isBreak  Boolean @default(false)\n  isActive Boolean @default(true)\n\n  school     School      @relation(fields: [schoolId], references: [id])\n  day        Day         @relation(fields: [dayId], references: [id])\n  timetables Timetable[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@unique([schoolId, academicYearId, dayId, periodNumber])\n  @@index([schoolId, academicYearId])\n}\n\nmodel AcademicYear {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  name String\n\n  startDate DateTime?\n\n  endDate DateTime?\n\n  isActive Boolean @default(true)\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  admissions      Admission[]\n  exams           Exam[]\n  academicRecords StudentAcademicRecord[]\n  feeStructures   FeeStructure[]\n  createdAt       DateTime                @default(now())\n\n  updatedAt DateTime @updatedAt\n}\n\nmodel Timetable {\n  id Int @id @default(autoincrement())\n\n  schoolId  Int\n  classId   Int\n  sectionId Int\n  subjectId Int\n  teacherId Int\n\n  dayId          Int\n  periodId       Int\n  academicYearId Int\n\n  startTime String\n  endTime   String\n  //   effectiveFrom DateTime\n  // effectiveTo   DateTime?\n\n  school  School  @relation(fields: [schoolId], references: [id])\n  class   Class   @relation(fields: [classId], references: [id])\n  section Section @relation(fields: [sectionId], references: [id])\n  subject Subject @relation(fields: [subjectId], references: [id])\n  teacher Teacher @relation(fields: [teacherId], references: [id])\n  period  Period  @relation(fields: [periodId], references: [id])\n  day     Day     @relation(fields: [dayId], references: [id])\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n  //   @@unique([schoolId, sectionId, dayId, periodId, academicYearId, effectiveFrom])\n  // @@unique([schoolId, teacherId, dayId, periodId, academicYearId, effectiveFrom])\n\n  @@unique([sectionId, dayId, periodId, academicYearId])\n  @@unique([teacherId, dayId, periodId, academicYearId])\n  @@index([schoolId, academicYearId])\n}\n\n// enum DayOfWeek {\n//   MONDAY\n//   TUESDAY\n//   WEDNESDAY\n//   THURSDAY\n//   FRIDAY\n//   SATURDAY\n// }\n\n/////////////////////////////\n// 👨‍🎓 STUDENTS & PARENTS\n/////////////////////////////\nmodel Student {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  userId Int? @unique\n\n  name String\n\n  profilePhoto String?\n\n  studentCode String @unique\n\n  dob DateTime?\n\n  gender Gender?\n\n  address String?\n\n  phoneNumber String?\n\n  email String?\n\n  isActive Boolean @default(true)\n\n  isDeleted Boolean @default(false)\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  user User? @relation(fields: [userId], references: [id])\n\n  admissions        Admission[]\n  examMarks         ExamMark[]\n  academicRecords   StudentAcademicRecord[]\n  attendanceRecords StudentAttendanceRecord[]\n  parents           StudentParent[]\n  studentFees       StudentFee[]\n  createdAt         DateTime                  @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  @@index([schoolId])\n}\n\nmodel StudentAcademicRecord {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  studentId Int\n\n  academicYearId Int\n\n  classId Int\n\n  sectionId Int?\n\n  rollNumber Int\n\n  admissionNo String\n\n  isCurrent Boolean @default(true)\n\n  status AcademicRecordStatus @default(ACTIVE)\n\n  promotedFromId Int?\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  student Student @relation(fields: [studentId], references: [id])\n\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id])\n\n  class            Class @relation(fields: [classId], references: [id])\n  transportRouteId Int?\n\n  transportRoute TransportRoute? @relation(fields: [transportRouteId], references: [id])\n  section        Section?        @relation(fields: [sectionId], references: [id])\n\n  promotedFrom StudentAcademicRecord? @relation(\"PromotionHistory\", fields: [promotedFromId], references: [id])\n\n  promotedTo StudentAcademicRecord[] @relation(\"PromotionHistory\")\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  @@index([schoolId])\n  @@index([studentId])\n  @@index([academicYearId])\n}\n\nenum AcademicRecordStatus {\n  ACTIVE\n  PROMOTED\n  REVERTED\n  TRANSFERRED\n  COMPLETED\n  DROPPED\n}\n\nenum Gender {\n  MALE\n  FEMALE\n  OTHER\n}\n\nmodel Parent {\n  id       Int @id @default(autoincrement())\n  userId   Int @unique\n  schoolId Int\n\n  fatherName       String?\n  fatherPhone      String?\n  fatherEmail      String?\n  fatherOccupation String?\n\n  motherName       String?\n  motherPhone      String?\n  motherEmail      String?\n  motherOccupation String?\n\n  guardianName     String?\n  guardianRelation String?\n  guardianPhone    String?\n  // ✅ Relations\n  user             User    @relation(fields: [userId], references: [id])\n  school           School  @relation(fields: [schoolId], references: [id])\n\n  students StudentParent[]\n\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  @@index([schoolId])\n}\n\nmodel StudentParent {\n  studentId Int\n  parentId  Int\n\n  // ✅ Relations\n  student Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n  parent  Parent  @relation(fields: [parentId], references: [id], onDelete: Cascade)\n\n  createdAt DateTime @default(now())\n\n  @@id([studentId, parentId])\n  @@index([parentId])\n}\n\nmodel Admission {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  studentId Int?\n\n  studentName String\n\n  dob DateTime?\n\n  gender      Gender?\n  address     String?\n  phoneNumber String?\n  email       String?\n\n  classId Int\n\n  sectionId Int?\n\n  academicYearId     Int\n  previousSchool     String?\n  previousClass      String?\n  previousPercentage Float?\n\n  rollNumber Int?\n\n  admissionNo String?\n\n  bloodGroup String?\n\n  nationality String?\n\n  religion String?\n\n  caste String?\n\n  aadharNumber String?\n\n  fatherName String?\n\n  fatherPhone String?\n\n  fatherEmail String?\n\n  fatherOccupation String?\n\n  motherName String?\n\n  motherPhone String?\n\n  motherEmail String?\n\n  motherOccupation String?\n\n  guardianName String?\n\n  guardianRelation String?\n\n  guardianPhone String?\n\n  guardianEmail String?\n  status        AdmissionStatus @default(PENDING)\n  approvedAt    DateTime?\n\n  admissionType AdmissionType @default(NEW)\n  admissionDate DateTime?     @default(now())\n\n  medium String?\n\n  previousBoard String?\n\n  tcNumber String?\n  student  Student? @relation(fields: [studentId], references: [id])\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  class Class @relation(fields: [classId], references: [id])\n\n  section Section? @relation(fields: [sectionId], references: [id])\n\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id])\n\n  createdAt DateTime @default(now())\n\n  @@index([schoolId])\n}\n\nenum AdmissionType {\n  NEW\n  TRANSFER\n  READMISSION\n}\n\nenum AdmissionStatus {\n  PENDING // 🔥 new application\n  APPROVED // 🔥 admin verified\n  ACTIVE\n  CANCELLED\n  TRANSFERRED\n  COMPLETED\n}\n\n/////////////////////////////\n// 📋 ATTENDANCE (ADVANCED)\n/////////////////////////////\n\nmodel StudentAttendanceSession {\n  id             Int      @id @default(autoincrement())\n  schoolId       Int\n  classId        Int\n  sectionId      Int?\n  markedById     Int\n  attendanceDate DateTime @db.Date\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(\"SchoolStudentAttendanceSessions\", fields: [schoolId], references: [id])\n\n  class Class @relation(fields: [classId], references: [id])\n\n  section Section? @relation(fields: [sectionId], references: [id])\n\n  markedBy User                      @relation(fields: [markedById], references: [id])\n  records  StudentAttendanceRecord[]\n\n  // =====================================\n  // UNIQUE\n  // =====================================\n  @@unique([schoolId, classId, sectionId, attendanceDate])\n  // ====================================\n  // INDEXES\n  // =====================================\n  @@index([schoolId, attendanceDate])\n}\n\nmodel StudentAttendanceRecord {\n  id Int @id @default(autoincrement())\n\n  sessionId Int\n\n  studentId Int\n\n  status AttendanceStatus\n\n  remarks String?\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  session StudentAttendanceSession @relation(fields: [sessionId], references: [id], onDelete: Cascade)\n\n  student Student @relation(fields: [studentId], references: [id], onDelete: Cascade)\n\n  // =====================================\n  // INDEXES\n  // =====================================\n\n  // =====================================\n  // UNIQUE\n  // =====================================\n\n  @@unique([sessionId, studentId])\n  @@index([studentId])\n}\n\nmodel EmployeeAttendance {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  employeeId Int\n\n  attendanceDate DateTime @db.Date\n\n  checkInTime DateTime?\n\n  checkOutTime DateTime?\n\n  status EmployeeAttendanceStatus\n\n  remarks String?\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(\"SchoolEmployeeAttendances\", fields: [schoolId], references: [id])\n\n  employee User @relation(fields: [employeeId], references: [id])\n\n  // =====================================\n  // UNIQUE\n  // =====================================\n  @@unique([employeeId, attendanceDate])\n  // =====================================\n  // INDEXES\n  // =====================================\n  @@index([schoolId, attendanceDate])\n}\n\nenum AttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n  HALF_DAY\n  LEAVE\n}\n\nenum EmployeeAttendanceStatus {\n  PRESENT\n  ABSENT\n  LATE\n  HALF_DAY\n  LEAVE\n  HOLIDAY\n}\n\n/////////////////////////////\n// 👩‍🏫 TEACHERS & STAFF\n/////////////////////////////\nmodel Staff {\n  id            Int @id @default(autoincrement())\n  userId        Int\n  schoolId      Int\n  designationId Int\n}\n\nmodel Designation {\n  id   Int    @id @default(autoincrement())\n  name String\n}\n\nmodel Payroll {\n  id      Int    @id @default(autoincrement())\n  staffId Int\n  salary  Float\n  month   String\n}\n\n/////////////////////////////\n// 💰 FEES & PAYMENTS\n/////////////////////////////\n\n////////////////////////////////////////////////////////\n// 💰 FEE HEAD MASTER\n////////////////////////////////////////////////////////\n\nmodel FeeHead {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  name String\n\n  description String?\n\n  isOptional Boolean @default(false)\n\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  feeStructureItems FeeStructureItem[]\n\n  @@unique([schoolId, name])\n}\n\n////////////////////////////////////////////////////////\n// 💰 FEE STRUCTURE\n////////////////////////////////////////////////////////\n\nmodel FeeStructure {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  academicYearId Int\n\n  classId Int\n\n  name String\n\n  dueDay    Int\n  frequency FeeFrequency @default(MONTHLY)\n  totalFee  Float        @default(0)\n\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id])\n\n  class Class @relation(fields: [classId], references: [id])\n\n  items FeeStructureItem[]\n\n  studentFees StudentFee[]\n\n  // =====================================\n  // UNIQUE\n  // =====================================\n\n  @@unique([schoolId, academicYearId, classId])\n  @@index([schoolId])\n  @@index([classId])\n}\n\n////////////////////////////////////////////////////////\n// 💰 FEE STRUCTURE ITEMS\n////////////////////////////////////////////////////////\n\nmodel FeeStructureItem {\n  id Int @id @default(autoincrement())\n\n  feeStructureId Int\n\n  feeHeadId Int\n\n  amount Float\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  feeStructure FeeStructure @relation(fields: [feeStructureId], references: [id], onDelete: Cascade)\n\n  feeHead FeeHead @relation(fields: [feeHeadId], references: [id])\n\n  @@unique([feeStructureId, feeHeadId])\n}\n\n////////////////////////////////////////////////////////\n// 🚌 TRANSPORT ROUTES\n////////////////////////////////////////////////////////\n\nmodel TransportRoute {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  name String\n\n  pickupPoint String?\n\n  amount Float\n\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  studentAcademicRecords StudentAcademicRecord[]\n\n  @@unique([schoolId, name])\n}\n\n////////////////////////////////////////////////////////\n// 📚 BOOK PACKAGE\n////////////////////////////////////////////////////////\n\nmodel BookPackage {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  classId Int\n\n  name String\n\n  amount Float\n\n  isActive Boolean @default(true)\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  class Class @relation(fields: [classId], references: [id])\n}\n\n////////////////////////////////////////////////////////\n// 🧾 STUDENT FEES / INVOICES\n////////////////////////////////////////////////////////\n\nmodel StudentFee {\n  id Int @id @default(autoincrement())\n\n  invoiceNo String? @unique\n\n  schoolId Int\n\n  studentId Int\n\n  feeStructureId Int\n\n  month Int?\n\n  year Int?\n\n  totalAmount Float\n\n  paidAmount Float @default(0)\n\n  dueAmount Float\n\n  lateFee Float @default(0)\n\n  discount Float @default(0)\n\n  isAdmissionFee Boolean @default(false)\n\n  status FeeStatus @default(PENDING)\n\n  dueDate DateTime\n\n  remarks String?\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  student Student @relation(fields: [studentId], references: [id])\n\n  feeStructure FeeStructure @relation(fields: [feeStructureId], references: [id])\n\n  receipts PaymentReceipt[]\n\n  @@unique([studentId, feeStructureId, month, year])\n  @@index([studentId])\n  @@index([schoolId])\n  @@index([status])\n}\n\n////////////////////////////////////////////////////////\n// 🧾 PAYMENT RECEIPTS\n////////////////////////////////////////////////////////\n\nmodel PaymentReceipt {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  studentFeeId Int\n\n  receiptNo String @unique\n\n  amount Float\n\n  paymentDate DateTime @default(now())\n\n  paymentMethod PaymentMethod\n\n  transactionId String?\n\n  remarks String?\n\n  receivedById Int?\n\n  status PaymentTransactionStatus @default(SUCCESS)\n\n  createdAt DateTime @default(now())\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  studentFee StudentFee @relation(fields: [studentFeeId], references: [id])\n\n  receivedBy User? @relation(fields: [receivedById], references: [id])\n}\n\n////////////////////////////////////////////////////////\n// ENUMS\n////////////////////////////////////////////////////////\n\nenum FeeStatus {\n  PAID\n\n  PARTIAL\n\n  PENDING\n\n  OVERDUE\n}\n\n////////////////////////////////////////////////////////\n\nenum PaymentMethod {\n  CASH\n\n  ONLINE\n\n  UPI\n\n  CARD\n\n  BANK_TRANSFER\n}\n\n////////////////////////////////////////////////////////\n\nenum PaymentTransactionStatus {\n  SUCCESS\n\n  FAILED\n\n  PENDING\n}\n\nenum FeeFrequency {\n  MONTHLY\n\n  QUARTERLY\n\n  HALF_YEARLY\n\n  YEARLY\n\n  ONE_TIME\n}\n\n/////////////////////////////\n// 📝 EXAMS & RESULTS\n/////////////////////////////\n\n/////////////////////////////\n// 📝 EXAM\n/////////////////////////////\n\nmodel Exam {\n  id Int @id @default(autoincrement())\n\n  schoolId Int\n\n  academicYearId Int\n\n  classId Int\n\n  sectionId Int?\n\n  name String\n\n  examType ExamType\n\n  startDate DateTime\n\n  endDate DateTime\n\n  isPublished Boolean @default(false)\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  school School @relation(fields: [schoolId], references: [id])\n\n  academicYear AcademicYear @relation(fields: [academicYearId], references: [id])\n\n  class Class @relation(fields: [classId], references: [id])\n\n  section Section? @relation(fields: [sectionId], references: [id])\n\n  subjects ExamSubject[]\n}\n\n/////////////////////////////\n// 📝 EXAM SUBJECTS\n/////////////////////////////\n\nmodel ExamSubject {\n  id Int @id @default(autoincrement())\n\n  examId Int\n\n  subjectId Int\n\n  examDate DateTime\n\n  totalMarks Float\n\n  passingMarks Float\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  exam Exam @relation(fields: [examId], references: [id], onDelete: Cascade)\n\n  subject Subject @relation(fields: [subjectId], references: [id])\n\n  marks ExamMark[]\n\n  // =====================================\n  // UNIQUE\n  // =====================================\n\n  @@unique([examId, subjectId])\n}\n\n/////////////////////////////\n// 📝 EXAM MARKS\n/////////////////////////////\n\nmodel ExamMark {\n  id Int @id @default(autoincrement())\n\n  examSubjectId Int\n\n  studentId Int\n\n  obtainedMarks Float\n\n  remarks String?\n\n  createdAt DateTime @default(now())\n\n  updatedAt DateTime @updatedAt\n\n  // =====================================\n  // RELATIONS\n  // =====================================\n\n  examSubject ExamSubject @relation(fields: [examSubjectId], references: [id], onDelete: Cascade)\n\n  student Student @relation(fields: [studentId], references: [id])\n\n  // =====================================\n  // UNIQUE\n  // =====================================\n\n  @@unique([examSubjectId, studentId])\n}\n\n/////////////////////////////\n// 📝 EXAM TYPE\n/////////////////////////////\n\nenum ExamType {\n  UNIT_TEST\n\n  MID_TERM\n\n  FINAL_EXAM\n\n  PRACTICAL\n}\n\n/////////////////////////////\n// 🧾 AUDIT LOG (ENTERPRISE)\n/////////////////////////////\n\nmodel AuditLog {\n  id        Int      @id @default(autoincrement())\n  userId    Int\n  action    String\n  entity    String\n  entityId  Int?\n  createdAt DateTime @default(now())\n}\n"
}

